/**
 * دمج كتالوج الـ 1001 صنف في قاعدة البيانات الحالية بدون تكرار أو حذف بيانات المستخدم
 */
export function mergeCatalogIntoDb(db: AccountingDB): { db: AccountingDB; addedCount: number } {
  const existingNames = new Set(db.products.map(p => p.name.trim().toLowerCase()));
  const existingCodes = new Set(db.products.map(p => p.code.trim().toLowerCase()));

  const updated: AccountingDB = JSON.parse(JSON.stringify(db));
  let addedCount = 0;

  let maxNum = 0;
  db.products.forEach(p => {
    const m = p.code.match(/\d+/);
    if (m) {
      const n = parseInt(m[0], 10);
      if (n > maxNum) maxNum = n;
    }
  });

  DEFAULT_CATALOG_1001.forEach(catItem => {
    const cleanName = catItem.name.trim().toLowerCase();
    if (!existingNames.has(cleanName)) {
      maxNum++;
      const uniqueCode = "PRD-" + String(maxNum).padStart(4, "0");
      updated.products.push({
        ...catItem,
        id: "prd_cat_" + Date.now().toString(36) + "_" + Math.random().toString(36).substr(2, 5),
        code: uniqueCode,
        barcode: catItem.barcode || uniqueCode
      });
      existingNames.add(cleanName);
      existingCodes.add(uniqueCode.toLowerCase());
      addedCount++;
    }
  });

  return { db: updated, addedCount };
}
